    if seed is None: return g
    # The 8s form parallel horizontal barriers. Mark their openings and the
    # connecting passages immediately above and between the barriers.
    walls=[r for r in range(R) if 8 in g[r]]
    if not walls: return g
    holes={r:[c for c,v in enumerate(g[r]) if v==0] for r in walls}
    def paint(r,c):
        if 0<=r<R and 0<=c<C and g[r][c]==0: g[r][c]=2
    for r in walls:
        for c in holes[r]: paint(r,c)
        if holes[r]:
            lo,hi=min(holes[r]),max(holes[r])
            if r>0:
                for c in range(lo,hi+1): paint(r-1,c)
    # Connect the marker to the first opening in the first barrier.
    fr=walls[0]
    if holes[fr] and seed[0]<fr:
        c0=seed[1]
        target=min(holes[fr],key=lambda c:abs(c-c0))
        for c in range(min(c0,target),max(c0,target)+1): paint(fr-1,c)
    # Carry each opening down until it meets another wall.
    for r in walls:
        for c in holes[r]:
            rr=r+1
            while rr<R and 8 not in g[rr]:
                paint(rr,c)
                rr+=1
    # A wider empty interval links the incoming tracks to the next barrier.
    for r,nr in zip(walls,walls[1:]):
        if nr-r>=3 and holes[nr]:
            rr=nr-1
            lo,hi=min(holes[nr]),max(holes[nr])
            if len(holes[nr])==1:
                lo,hi=0,C-1
            for c in range(lo,hi+1): paint(rr,c)
